@extends('admin.layout') @section('title','Campaigns') @section('heading','Campaign Management') @push('styles')<style>.item{margin-bottom:13px}.row{display:grid;grid-template-columns:2fr 1fr 1fr auto;gap:12px;align-items:center}.meta{font-size:12px;color:#667085;margin-top:4px}.status{display:inline-flex;padding:5px 9px;border-radius:99px;background:#eef1ff;color:#4459c5;font-size:11px;font-weight:850}@media(max-width:700px){.row{grid-template-columns:1fr}}</style>@endpush @section('content')@forelse($campaigns as $c)<section class="card item"><div class="row"><div><strong>{{ $c->app_name }}</strong><div class="meta">{{ $c->user->name }} · {{ $c->user->email }}</div><div class="meta">{{ $c->plan }} · {{ $c->duration_days }} days @if($c->ends_at) · Ends {{ $c->ends_at->format('M d, Y') }} @endif</div></div><strong>${{ number_format((float)$c->amount,2) }}</strong><span class="status">{{ ucfirst($c->status) }}</span><form method="POST" action="{{ route('admin.campaigns.update',$c) }}">@csrf @method('PATCH')<select class="input" name="status"><option value="pending">Pending</option><option value="active">Active</option><option value="completed">Completed</option><option value="cancelled">Cancelled</option></select><button class="btn" style="margin-top:6px;width:100%">Update</button></form></div></section>@empty<section class="card"><p class="muted">No campaigns yet.</p></section>@endforelse{{ $campaigns->links() }}@endsection